export default [{"id":"2933","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"3","aya_no":"1","aya_text":"طسٓمٓ","aya_text_emlaey":"طسم","aya_tafseer":"[1] طسٓمٓ سبق الكلام على الحروف المقطَّعة في أول سورة البقرة."},{"id":"2934","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"3","aya_no":"2","aya_text":"تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ","aya_text_emlaey":"تلك آيات الكتاب المبين","aya_tafseer":"[2] هذه آيات القرآن الموضِّح لكل شيء الفاصل بين الهدى والضلال."},{"id":"2935","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"4","aya_no":"3","aya_text":"لَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ أَلَّا يَكُونُواْ مُؤۡمِنِينَ","aya_text_emlaey":"لعلك باخع نفسك ألا يكونوا مؤمنين","aya_tafseer":"[3] لعلك -أيها الرسول- من شدة حرصك على هدايتهم مُهْلِك نفسك؛ لأنهم لم يصدِّقوا بك ولم يعملوا بهديك، فلا تفعل ذلك."},{"id":"2936","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"5","aya_no":"4","aya_text":"إِن نَّشَأۡ نُنَزِّلۡ عَلَيۡهِم مِّنَ ٱلسَّمَآءِ ءَايَةٗ فَظَلَّتۡ أَعۡنَٰقُهُمۡ لَهَا خَٰضِعِينَ","aya_text_emlaey":"إن نشأ ننـزل عليهم من السماء آية فظلت أعناقهم لها خاضعين","aya_tafseer":"[4] إن نشأ ننزل على المكذبين من قومك من السماء معجزة مخوِّفة لهم تلجئهم إلى الإيمان، فتصير أعناقهم خاضعة ذليلة، ولكننا لم نشأ ذلك؛ فإن الإيمان النافع هو الإيمان بالغيب اختياراً."},{"id":"2937","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"6","aya_no":"5","aya_text":"وَمَا يَأۡتِيهِم مِّن ذِكۡرٖ مِّنَ ٱلرَّحۡمَٰنِ مُحۡدَثٍ إِلَّا كَانُواْ عَنۡهُ مُعۡرِضِينَ","aya_text_emlaey":"وما يأتيهم من ذكر من الرحمن محدث إلا كانوا عنه معرضين","aya_tafseer":"[5] وما يجيء هؤلاء المشركين المكذبين مِن ذِكْرٍ من الرحمن مُحْدَث إنزاله، شيئاً بعد شيء، يأمرهم وينهاهم، ويذكرهم بالدين الحق إلا أعرضوا عنه ولم يقبلوه."},{"id":"2938","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"7","aya_no":"6","aya_text":"فَقَدۡ كَذَّبُواْ فَسَيَأۡتِيهِمۡ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ","aya_text_emlaey":"فقد كذبوا فسيأتيهم أنباء ما كانوا به يستهزئون","aya_tafseer":"[6] فقد كذَّبوا بالقرآن واستهزؤوا به، فسيأتيهم أخبار الأمر الذي كانوا يستهزئون به ويسخرون منه، وسيحلُّ بهم العذاب جزاء تمردهم على ربهم."},{"id":"2939","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"7","aya_text":"أَوَلَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجٖ كَرِيمٍ","aya_text_emlaey":"أو لم يروا إلى الأرض كم أنبتنا فيها من كل زوج كريم","aya_tafseer":"[7] أكذبوا ولم ينظروا إلى الأرض التي أنبتنا فيها من كل نوع حسن نافع من النبات، لا يقدر على إنباته إلا رب العالمين؟"},{"id":"2940","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"8","aya_text":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ","aya_text_emlaey":"إن في ذلك لآية وما كان أكثرهم مؤمنين","aya_tafseer":"[8] إن في إخراج النبات من الأرض لَدلالة واضحة على كمال قدرة الله، وما كان أكثر القوم مؤمنين."},{"id":"2941","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"9","aya_no":"9","aya_text":"وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","aya_text_emlaey":"وإن ربك لهو العزيز الرحيم","aya_tafseer":"[9] . وإن ربك لهو العزيز على كل مخلوق، الرحيم الذي وسعت رحمته كل شيء."},{"id":"2942","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"10","aya_text":"وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ","aya_text_emlaey":"وإذ نادى ربك موسى أن ائت القوم الظالمين","aya_tafseer":"[10] واذكر -أيها الرسول- لقومك إذ نادى ربك موسى: أن ائت القوم الظالمين،"},{"id":"2943","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"10","aya_no":"11","aya_text":"قَوۡمَ فِرۡعَوۡنَۚ أَلَا يَتَّقُونَ","aya_text_emlaey":"قوم فرعون ألا يتقون","aya_tafseer":"[11] قوم فرعون، وقل لهم: ألا يخافون عقاب الله تعالى، ويتركون ما هم عليه من الكفر والضلال؟"},{"id":"2944","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"10","aya_no":"12","aya_text":"قَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ","aya_text_emlaey":"قال رب إني أخاف أن يكذبون","aya_tafseer":"[12] قال موسى: رب إني أخاف أن يكذبوني في الرسالة،"},{"id":"2945","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"11","aya_no":"13","aya_text":"وَيَضِيقُ صَدۡرِي وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ","aya_text_emlaey":"ويضيق صدري ولا ينطلق لساني فأرسل إلى هارون","aya_tafseer":"[13] ويملأ صدري الغمُّ لتكذيبهم إياي، ولا ينطلق لساني بالدعوة فأرسِلْ جبريلَ بالوحي إلى أخي هارون؛ ليعاونني ويصدقني فيما أقول، ويُبيِّن لهم ما أخاطبهم به، فهو أفصح مني نطقاً."},{"id":"2946","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"12","aya_no":"14","aya_text":"وَلَهُمۡ عَلَيَّ ذَنۢبٞ فَأَخَافُ أَن يَقۡتُلُونِ","aya_text_emlaey":"ولهم علي ذنب فأخاف أن يقتلون","aya_tafseer":"[14] ولهم عليَّ ذنب في قتل رجل منهم، وهو القبطي، فأخاف أن يقتلوني به."},{"id":"2947","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"12","aya_no":"15","aya_text":"قَالَ كَلَّاۖ فَٱذۡهَبَا بِـَٔايَٰتِنَآۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ","aya_text_emlaey":"قال كلا فاذهبا بآياتنا إنا معكم مستمعون","aya_tafseer":"[15] قال الله لموسى: كَلَّا لن يقتلوك، وقد أجبت طلبك في هارون، فاذهبا بالمعجزات الدالة على صدقكما، إنا معكم بالعلم والحفظ والنصرة مستمعون."},{"id":"2948","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"16","aya_text":"فَأۡتِيَا فِرۡعَوۡنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"فأتيا فرعون فقولا إنا رسول رب العالمين","aya_tafseer":"[16] . فأتِيَا فرعون فقولا له: إنا مرسَلان إليك وإلى قومك من رب العالمين:"},{"id":"2949","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"14","aya_no":"17","aya_text":"أَنۡ أَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ","aya_text_emlaey":"أن أرسل معنا بني إسرائيل","aya_tafseer":"[17] أن اترك بني إسرائيل؛ ليذهبوا معنا."},{"id":"2950","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"15","aya_no":"18","aya_text":"قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِيدٗا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ سِنِينَ","aya_text_emlaey":"قال ألم نربك فينا وليدا ولبثت فينا من عمرك سنين","aya_tafseer":"[18] قال فرعون لموسى -ممتنّاً عليه-: ألم نُرَبِّك في منازلنا صغيراً، ومكثت في رعايتنا سنين من عُمُرك،"},{"id":"2951","jozz":"19","page":"367","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"19","aya_text":"وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِي فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"وفعلت فعلتك التي فعلت وأنت من الكافرين","aya_tafseer":"[19] وارتكبت جنايةً بقتلك رجلاً من قومي حين ضربته ودفعته، وأنت من الجاحدين نعمتي المنكرين ربوبيتي؟"},{"id":"2952","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"20","aya_text":"قَالَ فَعَلۡتُهَآ إِذٗا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ","aya_text_emlaey":"قال فعلتها إذا وأنا من الضالين","aya_tafseer":"[20] قال موسى مجيباً لفرعون: فعلتُ ما ذكرتَ قبل أن يوحي الله إليَّ ويبعثني رسولاً،"},{"id":"2953","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"2","aya_no":"21","aya_text":"فَفَرَرۡتُ مِنكُمۡ لَمَّا خِفۡتُكُمۡ فَوَهَبَ لِي رَبِّي حُكۡمٗا وَجَعَلَنِي مِنَ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"ففررت منكم لما خفتكم فوهب لي ربي حكما وجعلني من المرسلين","aya_tafseer":"[21] فخرجت من بينكم فارّاً إلى «مدين»، لمَّا خفت أن تقتلوني بما فعلتُ من غير عَمْد، فوهب لي ربي تفضلاً منه النبوة والعلم، وجعلني من المرسلين."},{"id":"2954","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"3","aya_no":"22","aya_text":"وَتِلۡكَ نِعۡمَةٞ تَمُنُّهَا عَلَيَّ أَنۡ عَبَّدتَّ بَنِيٓ إِسۡرَٰٓءِيلَ","aya_text_emlaey":"وتلك نعمة تمنها علي أن عبدت بني إسرائيل","aya_tafseer":"[22] أَوَتلك التربية في بيتك تَعُدُّها نعمة منك عليَّ، وقد جعلت بني إسرائيل عبيداً تُذَبِّح أبناءهم وتستبقي نساءهم للخدمة والامتهان؟"},{"id":"2955","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"3","aya_no":"23","aya_text":"قَالَ فِرۡعَوۡنُ وَمَا رَبُّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"قال فرعون وما رب العالمين","aya_tafseer":"[23] قال فرعون لموسى: وما رب العالمين الذي تدَّعي أنك رسوله؟"},{"id":"2956","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"4","aya_no":"24","aya_text":"قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ","aya_text_emlaey":"قال رب السموات والأرض وما بينهما إن كنتم موقنين","aya_tafseer":"[24] قال موسى: هو مالك ومدبر السموات والأرض وما بينهما، إن كنتم موقنين بذلك، فآمِنوا."},{"id":"2957","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"5","aya_no":"25","aya_text":"قَالَ لِمَنۡ حَوۡلَهُۥٓ أَلَا تَسۡتَمِعُونَ","aya_text_emlaey":"قال لمن حوله ألا تستمعون","aya_tafseer":"[25] قال فرعون لمن حوله مِن أشراف قومه: ألا تسمعون مقالة موسى العجيبة بوجود رب سواي؟"},{"id":"2958","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"6","aya_no":"26","aya_text":"قَالَ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"قال ربكم ورب آبائكم الأولين","aya_tafseer":"[26] قال موسى: الرب الذي أدعوكم إليه هو الذي خلقكم وخلق آباءكم الأولين، فكيف تعبدون مَن هو مخلوق مثلكم، وله آباء قد فَنَوْا كآبائكم؟"},{"id":"2959","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"27","aya_text":"قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِيٓ أُرۡسِلَ إِلَيۡكُمۡ لَمَجۡنُونٞ","aya_text_emlaey":"قال إن رسولكم الذي أرسل إليكم لمجنون","aya_tafseer":"[27] قال فرعون لخاصته يستثير غضبهم؛ لتكذيب موسى إياه: إن رسولكم الذي أرسل إليكم لمجنون، يتكلم كلاماً لا يُعْقَل"},{"id":"2960","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"28","aya_text":"قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ","aya_text_emlaey":"قال رب المشرق والمغرب وما بينهما إن كنتم تعقلون","aya_tafseer":"[28] قال موسى: رب المشرق والمغرب وما بينهما وما يكون فيهما من نور وظلمة، وهذا يستوجب الإيمان به وحده إن كنتم من أهل العقل والتدبر"},{"id":"2961","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"29","aya_text":"قَالَ لَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ","aya_text_emlaey":"قال لئن اتخذت إلها غيري لأجعلنك من المسجونين","aya_tafseer":"[29] قال فرعون لموسى مهدداً له: لئن اتخذت إلهاً غيري لأسجننك مع مَن سجنت."},{"id":"2962","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"30","aya_text":"قَالَ أَوَلَوۡ جِئۡتُكَ بِشَيۡءٖ مُّبِينٖ","aya_text_emlaey":"قال أو لو جئتك بشيء مبين","aya_tafseer":"[30] قال موسى: أتجعلني من المسجونين، ولو جئتك ببرهان قاطع يتبين منه صدقي؟"},{"id":"2963","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"10","aya_no":"31","aya_text":"قَالَ فَأۡتِ بِهِۦٓ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ","aya_text_emlaey":"قال فأت به إن كنت من الصادقين","aya_tafseer":"[31] قال فرعون: فأت به إن كنت من الصادقين في دعواك."},{"id":"2964","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"10","aya_no":"32","aya_text":"فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ","aya_text_emlaey":"فألقى عصاه فإذا هي ثعبان مبين","aya_tafseer":"[32] فألقى موسى عصاه فتحولت ثعباناً حقيقيّاً، ليس تمويهاً كما يفعل السحرة،"},{"id":"2965","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"11","aya_no":"33","aya_text":"وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّٰظِرِينَ","aya_text_emlaey":"ونـزع يده فإذا هي بيضاء للناظرين","aya_tafseer":"[33] وأخرج يده مِن فتحة قميصه المفتوحة إلى الصَّدْر، أو من تحت إبطه فإذا هي بيضاء كالثلج من غير برص، تَبْهَر الناظرين."},{"id":"2966","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"12","aya_no":"34","aya_text":"قَالَ لِلۡمَلَإِ حَوۡلَهُۥٓ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ","aya_text_emlaey":"قال للملإ حوله إن هذا لساحر عليم","aya_tafseer":"[34] قال فرعون لأشراف قومه خشية أن يؤمنوا: إن موسى لَساحر ماهر،"},{"id":"2967","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"13","aya_no":"35","aya_text":"يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِۦ فَمَاذَا تَأۡمُرُونَ","aya_text_emlaey":"يريد أن يخرجكم من أرضكم بسحره فماذا تأمرون","aya_tafseer":"[35] يريد أن يخرجكم بسحره من أرضكم، فأي شيء تشيرون به في شأنه أتبع رأيكم فيه؟"},{"id":"2968","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"14","aya_no":"36","aya_text":"قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ","aya_text_emlaey":"قالوا أرجه وأخاه وابعث في المدائن حاشرين","aya_tafseer":"[36] قال له قومه: أخِّر أمر موسى وهارون، وأرسِلْ في المدائن جنداً جامعين للسحرة،"},{"id":"2969","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"14","aya_no":"37","aya_text":"يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٖ","aya_text_emlaey":"يأتوك بكل سحار عليم","aya_tafseer":"[37] يأتوك بكلِّ مَن أجاد السحر، وتفوَّق في معرفته."},{"id":"2970","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"15","aya_no":"38","aya_text":"فَجُمِعَ ٱلسَّحَرَةُ لِمِيقَٰتِ يَوۡمٖ مَّعۡلُومٖ","aya_text_emlaey":"فجمع السحرة لميقات يوم معلوم","aya_tafseer":"[38] فَجُمِع السحرة، وحُدِّد لهم وقت معلوم، هو وقت الضحى من يوم الزينة الذي يتفرغون فيه من أشغالهم، ويجتمعون ويتزيَّنون؛ وذلك للاجتماع بموسى"},{"id":"2971","jozz":"19","page":"368","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"39","aya_text":"وَقِيلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ","aya_text_emlaey":"وقيل للناس هل أنتم مجتمعون","aya_tafseer":"[39] وحُثَّ الناس على الاجتماع؛ أملاً في أن تكون الغلبة للسحرة."},{"id":"2972","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"40","aya_text":"لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُواْ هُمُ ٱلۡغَٰلِبِينَ","aya_text_emlaey":"لعلنا نتبع السحرة إن كانوا هم الغالبين","aya_tafseer":"[40] إننا نطمع أن تكون الغلبة للسحرة، فنثبت على ديننا."},{"id":"2973","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"2","aya_no":"41","aya_text":"فَلَمَّا جَآءَ ٱلسَّحَرَةُ قَالُواْ لِفِرۡعَوۡنَ أَئِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ","aya_text_emlaey":"فلما جاء السحرة قالوا لفرعون أئن لنا لأجرا إن كنا نحن الغالبين","aya_tafseer":"[41] فلما جاء السحرة فرعون قالوا له: أإن لنا لأجراً مِن مال أو جاه، إنْ كنا نحن الغالبين لموسى؟"},{"id":"2974","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"3","aya_no":"42","aya_text":"قَالَ نَعَمۡ وَإِنَّكُمۡ إِذٗا لَّمِنَ ٱلۡمُقَرَّبِينَ","aya_text_emlaey":"قال نعم وإنكم إذا لمن المقربين","aya_tafseer":"[42] قال فرعون: نعم لكم عندي ما طلبتم مِن أجر، وإنكم حينئذ لمن المقربين لديَّ."},{"id":"2975","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"3","aya_no":"43","aya_text":"قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ","aya_text_emlaey":"قال لهم موسى ألقوا ما أنتم ملقون","aya_tafseer":"[43] قال موسى للسحرة مريداً إبطال سحرهم وإظهار أن ما جاء به ليس سحراً: ألقوا ما تريدون إلقاءه من السحر."},{"id":"2976","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"5","aya_no":"44","aya_text":"فَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَٰلِبُونَ","aya_text_emlaey":"فألقوا حبالهم وعصيهم وقالوا بعزة فرعون إنا لنحن الغالبون","aya_tafseer":"[44] فألقَوا حبالهم وعصيَّهم، وخُيِّل للناس أنها حيَّات تسعى، وأقسموا بعزة فرعون قائلين: إننا لنحن الغالبون."},{"id":"2977","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"5","aya_no":"45","aya_text":"فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ","aya_text_emlaey":"فألقى موسى عصاه فإذا هي تلقف ما يأفكون","aya_tafseer":"[45] فألقى موسى عصاه، فإذا هي حية عظيمة، تبتلع ما صدر منهم من إفك وتزوير."},{"id":"2978","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"46","aya_text":"فَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ","aya_text_emlaey":"فألقي السحرة ساجدين","aya_tafseer":"[46] فلما شاهدوا ذلك، وعلموا أنه ليس من تمويه السحرة، آمنوا بالله وسجدوا له،"},{"id":"2979","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"47","aya_text":"قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"قالوا آمنا برب العالمين","aya_tafseer":"[47] وقالوا: آمنَّا برب العالمين"},{"id":"2980","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"48","aya_text":"رَبِّ مُوسَىٰ وَهَٰرُونَ","aya_text_emlaey":"رب موسى وهارون","aya_tafseer":"[48] رب موسى وهارون."},{"id":"2981","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"9","aya_no":"49","aya_text":"قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَۚ لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَٰفٖ وَلَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ","aya_text_emlaey":"قال آمنتم له قبل أن آذن لكم إنه لكبيركم الذي علمكم السحر فلسوف تعلمون لأقطعن أيديكم وأرجلكم من خلاف ولأصلبنكم أجمعين","aya_tafseer":"[49] قال فرعون للسحرة مستنكراً: آمنتم لموسى بغير إذن مني، وقال موهماً أنَّ فِعْل موسى سحر: إنه لكبيركم الذي علَّمكم السحر، فلسوف تعلمون ما ينزل بكم من عقاب: لأقطعنَّ أيديكم وأرجلكم من خلاف: بقطع اليد اليمنى والرجل اليسرى أو عكس ذلك، ولأصلبنَّكم أجمعين."},{"id":"2982","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"10","aya_no":"50","aya_text":"قَالُواْ لَا ضَيۡرَۖ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ","aya_text_emlaey":"قالوا لا ضير إنا إلى ربنا منقلبون","aya_tafseer":"[50] قال السحرة لفرعون: لا ضرر علينا فيما يلحقنا من عقاب الدنيا، إنا راجعون إلى ربنا فيعطينا النعيم المقيم."},{"id":"2983","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"11","aya_no":"51","aya_text":"إِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ أَوَّلَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"إنا نطمع أن يغفر لنا ربنا خطايانا أن كنا أول المؤمنين","aya_tafseer":"[51]. إنا نرجو أن يغفر لنا ربنا خطايانا من الشرك وغيره؛ لكوننا أول المؤمنين في قومك."},{"id":"2984","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"12","aya_no":"52","aya_text":"۞ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِيٓ إِنَّكُم مُّتَّبَعُونَ","aya_text_emlaey":"وأوحينا إلى موسى أن أسر بعبادي إنكم متبعون","aya_tafseer":"[52] وأوحى الله إلى موسى عليه السلام: أَنْ سِرْ ليلاً بمن آمن من بني إسرائيل؛ لأن فرعون وجنوده متبعوكم حتى لا يدركوكم قبل وصولكم إلى البحر."},{"id":"2985","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"12","aya_no":"53","aya_text":"فَأَرۡسَلَ فِرۡعَوۡنُ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ","aya_text_emlaey":"فأرسل فرعون في المدائن حاشرين","aya_tafseer":"[53] فأرسل فرعون جنده -حين بلغه مسير بني إسرائيل- يجمعون جيشه من مدائن مملكته."},{"id":"2986","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"13","aya_no":"54","aya_text":"إِنَّ هَٰٓؤُلَآءِ لَشِرۡذِمَةٞ قَلِيلُونَ","aya_text_emlaey":"إن هؤلاء لشرذمة قليلون","aya_tafseer":"[54] قال فرعون: إن بني إسرائيل الذين فرُّوا مع موسى لَطائفة حقيرة قليلة العدد،"},{"id":"2987","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"55","aya_text":"وَإِنَّهُمۡ لَنَا لَغَآئِظُونَ","aya_text_emlaey":"وإنهم لنا لغائظون","aya_tafseer":"[55] وإنهم لمالئون صدورنا غيظاً؛ حيث خالفوا ديننا، وخرجوا بغير إذننا،"},{"id":"2988","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"56","aya_text":"وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ","aya_text_emlaey":"وإنا لجميع حاذرون","aya_tafseer":"[56] وإنا لجميع متيقظون مستعدون لهم."},{"id":"2989","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"14","aya_no":"57","aya_text":"فَأَخۡرَجۡنَٰهُم مِّن جَنَّٰتٖ وَعُيُونٖ","aya_text_emlaey":"فأخرجناهم من جنات وعيون","aya_tafseer":"[57] فأخرج الله فرعون وقومه من أرض «مصر» ذات البساتين وعيون الماء"},{"id":"2990","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"14","aya_no":"58","aya_text":"وَكُنُوزٖ وَمَقَامٖ كَرِيمٖ","aya_text_emlaey":"وكنوز ومقام كريم","aya_tafseer":"[58] وخزائن المال والمنازل الحسان."},{"id":"2991","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"59","aya_text":"كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا بَنِيٓ إِسۡرَٰٓءِيلَ","aya_text_emlaey":"كذلك وأورثناها بني إسرائيل","aya_tafseer":"[59] وكما أخرجناهم، جعلنا هذه الديار من بعدهم لبني إسرائيل."},{"id":"2992","jozz":"19","page":"369","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"60","aya_text":"فَأَتۡبَعُوهُم مُّشۡرِقِينَ","aya_text_emlaey":"فأتبعوهم مشرقين","aya_tafseer":"[60] فلحق فرعون وجنده موسى ومَن معه وقت شروق الشمس."},{"id":"2993","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"61","aya_text":"فَلَمَّا تَرَٰٓءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَٰبُ مُوسَىٰٓ إِنَّا لَمُدۡرَكُونَ","aya_text_emlaey":"فلما تراءى الجمعان قال أصحاب موسى إنا لمدركون","aya_tafseer":"[61] فلما رأى كل واحد من الفريقين الآخر قال أصحاب موسى: إنَّ جَمْعَ فرعون مُدْرِكنا ومهلكنا."},{"id":"2994","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"2","aya_no":"62","aya_text":"قَالَ كَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ","aya_text_emlaey":"قال كلا إن معي ربي سيهدين","aya_tafseer":"[62] قال موسى لهم: كَلَّا ليس الأمر كما ذكرتم فلن تُدْرَكوا؛ إن معي ربي بالنصر، سيهديني لما فيه نجاتي ونجاتكم."},{"id":"2995","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"3","aya_no":"63","aya_text":"فَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقٖ كَٱلطَّوۡدِ ٱلۡعَظِيمِ","aya_text_emlaey":"فأوحينا إلى موسى أن اضرب بعصاك البحر فانفلق فكان كل فرق كالطود العظيم","aya_tafseer":"[63] فأوحينا إلى موسى أن اضرب بعصاك البحر، فضرب، فانفلق البحر إلى اثني عشر طريقاً بعدد قبائل بني إسرائيل، فكانت كل قطعة انفصلت من البحر كالجبل العظيم."},{"id":"2996","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"4","aya_no":"64","aya_text":"وَأَزۡلَفۡنَا ثَمَّ ٱلۡأٓخَرِينَ","aya_text_emlaey":"وأزلفنا ثم الآخرين","aya_tafseer":"[64] وقرَّبْنا هناك فرعون وقومه حتى دخلوا البحر،"},{"id":"2997","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"4","aya_no":"65","aya_text":"وَأَنجَيۡنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجۡمَعِينَ","aya_text_emlaey":"وأنجينا موسى ومن معه أجمعين","aya_tafseer":"[65] وأنجينا موسى ومَن معه أجمعين. فاستمر البحر على انفلاقه حتى عبروا إلى البر،"},{"id":"2998","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"5","aya_no":"66","aya_text":"ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ","aya_text_emlaey":"ثم أغرقنا الآخرين","aya_tafseer":"[66] ثم أغرقنا فرعون ومن معه بإطباق البحر عليهم بعد أن دخلوا فيه متبعين موسى وقومه."},{"id":"2999","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"6","aya_no":"67","aya_text":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ","aya_text_emlaey":"إن في ذلك لآية وما كان أكثرهم مؤمنين","aya_tafseer":"[67] إن في ذلك الذي حدث لَعبرة عجيبة دالة على قدرة الله، وما صار أكثر أتباع فرعون مؤمنين مع هذه العلامة الباهرة."},{"id":"3000","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"68","aya_text":"وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","aya_text_emlaey":"وإن ربك لهو العزيز الرحيم","aya_tafseer":"[68] وإن ربك لهو العزيز الرحيم، بعزته أهلك الكافرين المكذبين، وبرحمته نجَّى موسى ومَن معه أجمعين."},{"id":"3001","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"69","aya_text":"وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ إِبۡرَٰهِيمَ","aya_text_emlaey":"واتل عليهم نبأ إبراهيم","aya_tafseer":"[69] واقصص على الكافرين -أيها الرسول- خبر إبراهيم"},{"id":"3002","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"70","aya_text":"إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ","aya_text_emlaey":"إذ قال لأبيه وقومه ما تعبدون","aya_tafseer":"[70] حين قال لأبيه وقومه: أي شيء تعبدونه؟"},{"id":"3003","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"71","aya_text":"قَالُواْ نَعۡبُدُ أَصۡنَامٗا فَنَظَلُّ لَهَا عَٰكِفِينَ","aya_text_emlaey":"قالوا نعبد أصناما فنظل لها عاكفين","aya_tafseer":"[71] قالوا: نعبد أصناماً، فنَعْكُف على عبادتها."},{"id":"3004","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"9","aya_no":"72","aya_text":"قَالَ هَلۡ يَسۡمَعُونَكُمۡ إِذۡ تَدۡعُونَ","aya_text_emlaey":"قال هل يسمعونكم إذ تدعون","aya_tafseer":"[72] قال إبراهيم منبهاً على فساد مذهبهم: هل يسمعون دعاءكم إذ تدعونهم،"},{"id":"3005","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"73","aya_text":"أَوۡ يَنفَعُونَكُمۡ أَوۡ يَضُرُّونَ","aya_text_emlaey":"أو ينفعونكم أو يضرون","aya_tafseer":"[73] أو يقدِّمون لكم نفعاً إذا عبدتموهم، أو يصيبونكم بضر إذا تركتم عبادتهم؟"},{"id":"3006","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"10","aya_no":"74","aya_text":"قَالُواْ بَلۡ وَجَدۡنَآ ءَابَآءَنَا كَذَٰلِكَ يَفۡعَلُونَ","aya_text_emlaey":"قالوا بل وجدنا آباءنا كذلك يفعلون","aya_tafseer":"[74] قالوا: لا يكون منهم شيء من ذلك، ولكننا وجدنا آباءنا يعبدونهم، فقلَّدناهم فيما كانوا يفعلون."},{"id":"3007","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"11","aya_no":"75","aya_text":"قَالَ أَفَرَءَيۡتُم مَّا كُنتُمۡ تَعۡبُدُونَ","aya_text_emlaey":"قال أفرأيتم ما كنتم تعبدون","aya_tafseer":"[75] قال إبراهيم: أفأبصرتم بتدبر ما كنتم تعبدون من الأصنام التي لا تسمع ولا تنفع ولا تضر،"},{"id":"3008","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"11","aya_no":"76","aya_text":"أَنتُمۡ وَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ","aya_text_emlaey":"أنتم وآباؤكم الأقدمون","aya_tafseer":"[76] أنتم وآباؤكم الأقدمون من قبلكم؟"},{"id":"3009","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"12","aya_no":"77","aya_text":"فَإِنَّهُمۡ عَدُوّٞ لِّيٓ إِلَّا رَبَّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"فإنهم عدو لي إلا رب العالمين","aya_tafseer":"[77] فإن ما تعبدونهم من دون الله أعداء لي، لكن رب العالمين ومالك أمرهم هو وحده الذي أعبده."},{"id":"3010","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"12","aya_no":"78","aya_text":"ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ","aya_text_emlaey":"الذي خلقني فهو يهدين","aya_tafseer":"[78] هو الذي خلقني في أحسن صورة فهو يرشدني إلى مصالح الدنيا والآخرة،"},{"id":"3011","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"13","aya_no":"79","aya_text":"وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ","aya_text_emlaey":"والذي هو يطعمني ويسقين","aya_tafseer":"[79] وهو الذي ينعم عليَّ بالطعام والشراب،"},{"id":"3012","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"80","aya_text":"وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ","aya_text_emlaey":"وإذا مرضت فهو يشفين","aya_tafseer":"[80] وإذا أصابني مرض فهو الذي يَشْفيني ويعافيني منه،"},{"id":"3013","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"14","aya_no":"81","aya_text":"وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ","aya_text_emlaey":"والذي يميتني ثم يحيين","aya_tafseer":"[81] وهو الذي يميتني في الدنيا بقبض روحي، ثم يحييني يوم القيامة، لا يقدر على ذلك أحد سواه،"},{"id":"3014","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"15","aya_no":"82","aya_text":"وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ","aya_text_emlaey":"والذي أطمع أن يغفر لي خطيئتي يوم الدين","aya_tafseer":"[82] والذي أطمع أن يتجاوز عن ذنبي يوم الجزاء."},{"id":"3015","jozz":"19","page":"370","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"83","aya_text":"رَبِّ هَبۡ لِي حُكۡمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ","aya_text_emlaey":"رب هب لي حكما وألحقني بالصالحين","aya_tafseer":"[83] قال إبراهيم داعياً ربه: ربِّ امنحني العلم والفهم، وألحقني بالصالحين، واجمع بيني وبينهم في الجنة."},{"id":"3016","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"84","aya_text":"وَٱجۡعَل لِّي لِسَانَ صِدۡقٖ فِي ٱلۡأٓخِرِينَ","aya_text_emlaey":"واجعل لي لسان صدق في الآخرين","aya_tafseer":"[84] واجعل لي ثناء حسناً وذكراً جميلاً في الذين يأتون بعدي إلى يوم القيامة."},{"id":"3017","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"2","aya_no":"85","aya_text":"وَٱجۡعَلۡنِي مِن وَرَثَةِ جَنَّةِ ٱلنَّعِيمِ","aya_text_emlaey":"واجعلني من ورثة جنة النعيم","aya_tafseer":"[85] واجعلني من عبادك الذين تورثهم نعيم الجنة."},{"id":"3018","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"2","aya_no":"86","aya_text":"وَٱغۡفِرۡ لِأَبِيٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ","aya_text_emlaey":"واغفر لأبي إنه كان من الضالين","aya_tafseer":"[86] هذا دعاء من إبراهيم -عليه السلام- أن ينقذ الله أباه من الضلال إلى الهدى، فيغفر له ويتجاوز عنه، كما وعد إبراهيم أباه بالدعاء له، فلما تبيَّن له أنه مستمر في الكفر والشرك إلى أن يموت تبرأ منه."},{"id":"3019","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"3","aya_no":"87","aya_text":"وَلَا تُخۡزِنِي يَوۡمَ يُبۡعَثُونَ","aya_text_emlaey":"ولا تخزني يوم يبعثون","aya_tafseer":"[87] ولا تُلْحق بي الذل، يوم يخرج الناس من القبور للحساب والجزاء،"},{"id":"3020","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"3","aya_no":"88","aya_text":"يَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ","aya_text_emlaey":"يوم لا ينفع مال ولا بنون","aya_tafseer":"[88] يوم لا ينفع المال والبنون أحداً من العباد،"},{"id":"3021","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"4","aya_no":"89","aya_text":"إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبٖ سَلِيمٖ","aya_text_emlaey":"إلا من أتى الله بقلب سليم","aya_tafseer":"[89] إلا مَن أتى الله بقلب سليم من الكفر والنفاق والرذيلة."},{"id":"3022","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"4","aya_no":"90","aya_text":"وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ","aya_text_emlaey":"وأزلفت الجنة للمتقين","aya_tafseer":"[90] وقُرِّبت الجنة للذين اجتنبوا الكفر والمعاصي، وأقبلوا على الله بالطاعة."},{"id":"3023","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"5","aya_no":"91","aya_text":"وَبُرِّزَتِ ٱلۡجَحِيمُ لِلۡغَاوِينَ","aya_text_emlaey":"وبرزت الجحيم للغاوين","aya_tafseer":"[91] وأُظهرت النار للكافرين الذين ضَلُّوا عن الهدى، وتجرَّؤوا على محارم الله وكذَّبوا رسله."},{"id":"3024","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"5","aya_no":"92","aya_text":"وَقِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تَعۡبُدُونَ","aya_text_emlaey":"وقيل لهم أين ما كنتم تعبدون","aya_tafseer":"[92] وقيل لهم توبيخاً: أين آلهتكم التي كنتم تعبدونها"},{"id":"3025","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"6","aya_no":"93","aya_text":"مِن دُونِ ٱللَّهِ هَلۡ يَنصُرُونَكُمۡ أَوۡ يَنتَصِرُونَ","aya_text_emlaey":"من دون الله هل ينصرونكم أو ينتصرون","aya_tafseer":"[93] مِن دون الله، وتزعمون أنها تشفع لكم اليوم؟ هل ينصرونكم، فيدفعون العذاب عنكم، أو ينتصرون بدفع العذاب عن أنفسهم؟ لا شيء من ذلك."},{"id":"3026","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"94","aya_text":"فَكُبۡكِبُواْ فِيهَا هُمۡ وَٱلۡغَاوُۥنَ","aya_text_emlaey":"فكبكبوا فيها هم والغاوون","aya_tafseer":"[94] فجُمِعوا وألقُوا في جهنم على رؤوسهم مرَّة بعد مرَّة إلى أن استقرُّوا فيها، هم والذين أضلوهم،"},{"id":"3027","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"7","aya_no":"95","aya_text":"وَجُنُودُ إِبۡلِيسَ أَجۡمَعُونَ","aya_text_emlaey":"وجنود إبليس أجمعون","aya_tafseer":"[95] وأعوان إبليس الذين زيَّنوا لهم الشر، لم يُفْلِت منهم أحد."},{"id":"3028","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"96","aya_text":"قَالُواْ وَهُمۡ فِيهَا يَخۡتَصِمُونَ","aya_text_emlaey":"قالوا وهم فيها يختصمون","aya_tafseer":"[96] قالوا معترفين بخطئهم، وهم يتنازعون في جهنم مع مَن أضلوهم:"},{"id":"3029","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"8","aya_no":"97","aya_text":"تَٱللَّهِ إِن كُنَّا لَفِي ضَلَٰلٖ مُّبِينٍ","aya_text_emlaey":"تالله إن كنا لفي ضلال مبين","aya_tafseer":"[97] تالله إننا كنا في الدنيا في ضلال واضح لا خفاء فيه؛"},{"id":"3030","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"98","aya_text":"إِذۡ نُسَوِّيكُم بِرَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"إذ نسويكم برب العالمين","aya_tafseer":"[98] إذ نسويكم برب العالمين المستحق للعبادة وحده."},{"id":"3031","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"9","aya_no":"99","aya_text":"وَمَآ أَضَلَّنَآ إِلَّا ٱلۡمُجۡرِمُونَ","aya_text_emlaey":"وما أضلنا إلا المجرمون","aya_tafseer":"99] وما أوقعنا في هذا المصير السيِّئ إلا المجرمون الذين دعونا إلى عبادة غير الله فاتبعناهم."},{"id":"3032","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"100","aya_text":"فَمَا لَنَا مِن شَٰفِعِينَ","aya_text_emlaey":"فما لنا من شافعين","aya_tafseer":"[100] فلا أحدَ يشفع لنا، ويخلِّصنا من العذاب،"},{"id":"3033","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"101","aya_text":"وَلَا صَدِيقٍ حَمِيمٖ","aya_text_emlaey":"ولا صديق حميم","aya_tafseer":"[101] ولا مَن يَصْدُق في مودتنا ويشفق علينا"},{"id":"3034","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"10","aya_no":"102","aya_text":"فَلَوۡ أَنَّ لَنَا كَرَّةٗ فَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"فلو أن لنا كرة فنكون من المؤمنين","aya_tafseer":"[102] فليت لنا رجعة إلى الدنيا، فنصير من جملة المؤمنين الناجين."},{"id":"3035","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"11","aya_no":"103","aya_text":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ","aya_text_emlaey":"إن في ذلك لآية وما كان أكثرهم مؤمنين","aya_tafseer":"[103] إن في نبأ إبراهيم السابق لَعبرة لِمن يعتبر، وما صار أكثر الذين سمعوا هذا النبأ مؤمنين."},{"id":"3036","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"11","aya_no":"104","aya_text":"وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","aya_text_emlaey":"وإن ربك لهو العزيز الرحيم","aya_tafseer":"[104] وإن ربك لهو العزيز القادر على الانتقام من المكذبين، الرحيم بعباده المؤمنين."},{"id":"3037","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"12","aya_no":"105","aya_text":"كَذَّبَتۡ قَوۡمُ نُوحٍ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"كذبت قوم نوح المرسلين","aya_tafseer":"[105] كَذَّبت قوم نوح رسالة نبيهم، فكانوا بهذا مكذبين لجميع الرسل؛ لأن كل رسول يأمر بتصديق جميع الرسل."},{"id":"3038","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"12","aya_no":"106","aya_text":"إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ أَلَا تَتَّقُونَ","aya_text_emlaey":"إذ قال لهم أخوهم نوح ألا تتقون","aya_tafseer":"[106] إذ قال لهم أخوهم نوح: ألا تخشون الله بترك عبادة غيره؟"},{"id":"3039","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"107","aya_text":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","aya_text_emlaey":"إني لكم رسول أمين","aya_tafseer":"[107] إني لكم رسول أمين فيما أبلغكم،"},{"id":"3040","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"108","aya_text":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","aya_text_emlaey":"فاتقوا الله وأطيعون","aya_tafseer":"[108] فاجعلوا الإيمان وقاية لكم من عذاب الله وأطيعوني فيما آمركم به من عبادته وحده."},{"id":"3041","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"14","aya_no":"109","aya_text":"وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"وما أسألكم عليه من أجر إن أجري إلا على رب العالمين","aya_tafseer":"[109]. وما أطلب منكم أجراً على تبليغ الرسالة، ما أجري إلا على رب العالمين المتصرفِ في خلقه،"},{"id":"3042","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"15","aya_no":"110","aya_text":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","aya_text_emlaey":"فاتقوا الله وأطيعون","aya_tafseer":"[110] فاحذروا عقابه، وأطيعوني بامتثال أوامره، واجتناب نواهيه."},{"id":"3043","jozz":"19","page":"371","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"111","aya_text":"۞ قَالُوٓاْ أَنُؤۡمِنُ لَكَ وَٱتَّبَعَكَ ٱلۡأَرۡذَلُونَ","aya_text_emlaey":"قالوا أنؤمن لك واتبعك الأرذلون","aya_tafseer":"[111] قال له قومه: كيف نصدِّقك ونتبعك، والذين اتبعوك أراذل الناس وأسافلهم؟"},{"id":"3044","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"112","aya_text":"قَالَ وَمَا عِلۡمِي بِمَا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"قال وما علمي بما كانوا يعملون","aya_tafseer":"[112] فأجابهم نوح -عليه السلام- بقوله: لست مكلفاً بمعرفة أعمالهم، إنما كُلِّفت أن أدعوهم إلى الإيمان. والاعتبار بالإيمان، لا بالحسب والنسب والحِرَف والصنائع."},{"id":"3045","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"2","aya_no":"113","aya_text":"إِنۡ حِسَابُهُمۡ إِلَّا عَلَىٰ رَبِّيۖ لَوۡ تَشۡعُرُونَ","aya_text_emlaey":"إن حسابهم إلا على ربي لو تشعرون","aya_tafseer":"[113] ما حسابهم للجزاء على أعمالهم وبواطنهم إلا على ربي المطَّلِع على السرائر. لو كنتم تشعرون بذلك لما قلتم هذا الكلام."},{"id":"3046","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"2","aya_no":"114","aya_text":"وَمَآ أَنَا۠ بِطَارِدِ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"وما أنا بطارد المؤمنين","aya_tafseer":"[114] وما أنا بطارد الذين يؤمنون بدعوتي، مهما تكن حالهم؛ تلبية لرغبتكم كي تؤمنوا بي"},{"id":"3047","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"3","aya_no":"115","aya_text":"إِنۡ أَنَا۠ إِلَّا نَذِيرٞ مُّبِينٞ","aya_text_emlaey":"إن أنا إلا نذير مبين","aya_tafseer":"[115] ما أنا إلا نذير بيِّن الإنذار"},{"id":"3048","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"3","aya_no":"116","aya_text":"قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰنُوحُ لَتَكُونَنَّ مِنَ ٱلۡمَرۡجُومِينَ","aya_text_emlaey":"قالوا لئن لم تنته يانوح لتكونن من المرجومين","aya_tafseer":"[116] عدل قوم نوح عن المحاورة إلى التهديد، فقالوا له: لئن لم ترجع -يا نوح- عن دعوتك لتكوننَّ مِنَ المقتولين رمياً بالحجارة."},{"id":"3049","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"4","aya_no":"117","aya_text":"قَالَ رَبِّ إِنَّ قَوۡمِي كَذَّبُونِ","aya_text_emlaey":"قال رب إن قومي كذبون","aya_tafseer":"[117] فلما سمع نوح قولهم هذا دعا ربه بقوله: رب إن قومي أصروا على تكذيبي،"},{"id":"3050","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"5","aya_no":"118","aya_text":"فَٱفۡتَحۡ بَيۡنِي وَبَيۡنَهُمۡ فَتۡحٗا وَنَجِّنِي وَمَن مَّعِيَ مِنَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"فافتح بيني وبينهم فتحا ونجني ومن معي من المؤمنين","aya_tafseer":"[118] فاحكم بيني وبينهم حكماً تُهلك به مَن جحد توحيدك وكذَّب رسولك، ونجني ومَن معي من المؤمنين مما تعذب به الكافرين."},{"id":"3051","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"5","aya_no":"119","aya_text":"فَأَنجَيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ","aya_text_emlaey":"فأنجيناه ومن معه في الفلك المشحون","aya_tafseer":"[119] فأنجيناه ومَن معه في السفينة المملوءة بصنوف المخلوقات التي حملها معه."},{"id":"3052","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"120","aya_text":"ثُمَّ أَغۡرَقۡنَا بَعۡدُ ٱلۡبَاقِينَ","aya_text_emlaey":"ثم أغرقنا بعد الباقين","aya_tafseer":"[120] ثم أغرقنا -بعد إنجاء نوح ومن معه- الباقين الذين لم يؤمنوا مِن قومه وردُّوا عليه النصيحة."},{"id":"3053","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"7","aya_no":"121","aya_text":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ","aya_text_emlaey":"إن في ذلك لآية وما كان أكثرهم مؤمنين","aya_tafseer":"[121] إن في نبأ نوح وما كان من إنجاء المؤمنين وإهلاك المكذبين لَعلامة وعبرةً عظيمة لمن بعدهم، وما كان أكثر الذين سمعوا هذه القصة مؤمنين بالله وبرسوله وشرعه."},{"id":"3054","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"122","aya_text":"وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","aya_text_emlaey":"وإن ربك لهو العزيز الرحيم","aya_tafseer":"[122] و إن ربك لهو العزيز في انتقامه ممن كفر به وخالف أمره، الرحيم بعباده المؤمنين."},{"id":"3055","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"8","aya_no":"123","aya_text":"كَذَّبَتۡ عَادٌ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"كذبت عاد المرسلين","aya_tafseer":"[123] كذَّبت قبيلة عاد رسولهم هوداً -عليه السلام- فكانوا بهذا مكذِّبين لجميع الرسل؛ لاتحاد دعوتهم في أصولها وغايتها."},{"id":"3056","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"124","aya_text":"إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ هُودٌ أَلَا تَتَّقُونَ","aya_text_emlaey":"إذ قال لهم أخوهم هود ألا تتقون","aya_tafseer":"[124] إذ قال لهم أخوهم هود: ألا تخشون الله فتخلصوا له العبادة؟"},{"id":"3057","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"9","aya_no":"125","aya_text":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","aya_text_emlaey":"إني لكم رسول أمين","aya_tafseer":"[125] إني مرسَل إليكم لهدايتكم وإرشادكم، حفيظ على رسالة الله، أبلِّغها لكم كما أمرني ربي،"},{"id":"3058","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"126","aya_text":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","aya_text_emlaey":"فاتقوا الله وأطيعون","aya_tafseer":"[126] فخافوا عقاب الله وأطيعوني فيما جئتكم به مِن عند الله."},{"id":"3059","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"10","aya_no":"127","aya_text":"وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"وما أسألكم عليه من أجر إن أجري إلا على رب العالمين","aya_tafseer":"[127] . وما أطلب منكم على إرشادكم إلى التوحيد أيَّ نوع من أنواع الأجر، ما أجري إلا على رب العالمين."},{"id":"3060","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"11","aya_no":"128","aya_text":"أَتَبۡنُونَ بِكُلِّ رِيعٍ ءَايَةٗ تَعۡبَثُونَ","aya_text_emlaey":"أتبنون بكل ريع آية تعبثون","aya_tafseer":"[128] أتبنون بكل مكان مرتفع بناء عالياً تشرفون منه فتسخرون مِنَ المارة؟ وذلك عبث وإسراف لا يعود عليكم بفائدة في الدين أو الدنيا،"},{"id":"3061","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"11","aya_no":"129","aya_text":"وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمۡ تَخۡلُدُونَ","aya_text_emlaey":"وتتخذون مصانع لعلكم تخلدون","aya_tafseer":"[129] وتتخذون قصوراً منيعة وحصوناً مشيَّدة، كأنكم تخلدون في الدنيا ولا تموتون،"},{"id":"3062","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"12","aya_no":"130","aya_text":"وَإِذَا بَطَشۡتُم بَطَشۡتُمۡ جَبَّارِينَ","aya_text_emlaey":"وإذا بطشتم بطشتم جبارين","aya_tafseer":"[130] وإذا بطشتم بأحد من الخلق قتلاً أو ضرباً، فعلتم ذلك قاهرين ظالمين."},{"id":"3063","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"12","aya_no":"131","aya_text":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","aya_text_emlaey":"فاتقوا الله وأطيعون","aya_tafseer":"[131] فخافوا الله، وامتثلوا ما أدعوكم إليه فإنه أنفع لكم،"},{"id":"3064","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"132","aya_text":"وَٱتَّقُواْ ٱلَّذِيٓ أَمَدَّكُم بِمَا تَعۡلَمُونَ","aya_text_emlaey":"واتقوا الذي أمدكم بما تعلمون","aya_tafseer":"[132] واخشوا الله الذي أعطاكم من أنواع النعم مالا خفاء فيه عليكم،"},{"id":"3065","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"133","aya_text":"أَمَدَّكُم بِأَنۡعَٰمٖ وَبَنِينَ","aya_text_emlaey":"أمدكم بأنعام وبنين","aya_tafseer":"[133] أعطاكم الأنعام: من الإبل والبقر والغنم، وأعطاكم الأولاد،"},{"id":"3066","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"14","aya_no":"134","aya_text":"وَجَنَّٰتٖ وَعُيُونٍ","aya_text_emlaey":"وجنات وعيون","aya_tafseer":"[134] وأعطاكم البساتين المثمرة، وفجَّر لكم الماء من العيون الجارية."},{"id":"3067","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"14","aya_no":"135","aya_text":"إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ","aya_text_emlaey":"إني أخاف عليكم عذاب يوم عظيم","aya_tafseer":"[135] قال هود -عليه السَّلام- محذراً لهم: إني أخاف إن أصررتم على ما أنتم عليه من التكذيب والظلم وكُفْر النِّعَم، أن ينزل الله بكم عذاباً في يوم تعظم شدته من هول عذابه."},{"id":"3068","jozz":"19","page":"372","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"136","aya_text":"قَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ","aya_text_emlaey":"قالوا سواء علينا أوعظت أم لم تكن من الواعظين","aya_tafseer":"[136] قالوا له: يستوي عندنا تذكيرك وتخويفك لنا وتركه، فلن نؤمن لك."},{"id":"3069","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"137","aya_text":"إِنۡ هَٰذَآ إِلَّا خُلُقُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"إن هذا إلا خلق الأولين","aya_tafseer":"[137] وقالوا: ما هذا الذي نحن عليه إلا دين الأولين وعاداتهم،"},{"id":"3070","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"138","aya_text":"وَمَا نَحۡنُ بِمُعَذَّبِينَ","aya_text_emlaey":"وما نحن بمعذبين","aya_tafseer":"[138] وما نحن بمعذبين على ما نفعل مما حَذَّرْتنا منه من العذاب."},{"id":"3071","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"2","aya_no":"139","aya_text":"فَكَذَّبُوهُ فَأَهۡلَكۡنَٰهُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ","aya_text_emlaey":"فكذبوه فأهلكناهم إن في ذلك لآية وما كان أكثرهم مؤمنين","aya_tafseer":"[139] فاستمَرُّوا على تكذيبه، فأهلكهم الله بريح باردة شديدة. إن في ذلك الإهلاك لَعبرة لمن بعدهم، وما كان أكثر الذين سمعوا قصتهم مؤمنين بك."},{"id":"3072","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"3","aya_no":"140","aya_text":"وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","aya_text_emlaey":"وإن ربك لهو العزيز الرحيم","aya_tafseer":"[140] . وإن ربك لهو العزيز الغالب على ما يريده من إهلاك المكذبين، الرحيم بالمؤمنين."},{"id":"3073","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"3","aya_no":"141","aya_text":"كَذَّبَتۡ ثَمُودُ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"كذبت ثمود المرسلين","aya_tafseer":"[141] كذَّبت قبيلة ثمود رسولهم صالحاً في رسالته ودعوته إلى توحيد الله، فكانوا بهذا مكذِّبين لجميع الرسل؛ لأنهم جميعاً يدعون إلى توحيد الله."},{"id":"3074","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"4","aya_no":"142","aya_text":"إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ صَٰلِحٌ أَلَا تَتَّقُونَ","aya_text_emlaey":"إذ قال لهم أخوهم صالح ألا تتقون","aya_tafseer":"[142] إذ قال لهم أخوهم صالح: ألا تخشون عقاب الله، فتُفرِدوه بالعبادة؟"},{"id":"3075","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"4","aya_no":"143","aya_text":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","aya_text_emlaey":"إني لكم رسول أمين","aya_tafseer":"[143] إني مرسَل من الله إليكم، حفيظ على هذه الرسالة كما تلقيتها عن الله،"},{"id":"3076","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"5","aya_no":"144","aya_text":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","aya_text_emlaey":"فاتقوا الله وأطيعون","aya_tafseer":"[144] فاحذروا عقابه تعالى، وامتثلوا ما دعوتكم إليه."},{"id":"3077","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"6","aya_no":"145","aya_text":"وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"وما أسألكم عليه من أجر إن أجري إلا على رب العالمين","aya_tafseer":"[145] وما أطلب منكم على نصحي وإرشادي لكم أيَّ جزاء، ما جزائي إلا على رب العالمين."},{"id":"3078","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"146","aya_text":"أَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ","aya_text_emlaey":"أتتركون في ما هاهنا آمنين","aya_tafseer":"[146] أيترككم ربكم فيما أنتم فيه من النعيم مستقرين في هذه الدنيا آمنين من العذاب والزوال والموت؟"},{"id":"3079","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"147","aya_text":"فِي جَنَّٰتٖ وَعُيُونٖ","aya_text_emlaey":"في جنات وعيون","aya_tafseer":"[147] في حدائق مثمرة وعيون جارية"},{"id":"3080","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"148","aya_text":"وَزُرُوعٖ وَنَخۡلٖ طَلۡعُهَا هَضِيمٞ","aya_text_emlaey":"وزروع ونخل طلعها هضيم","aya_tafseer":"[148] وزروع كثيرة ونخل ثمرها يانع لين نضيج،"},{"id":"3081","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"149","aya_text":"وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتٗا فَٰرِهِينَ","aya_text_emlaey":"وتنحتون من الجبال بيوتا فارهين","aya_tafseer":"[149] وتنحتون من الجبال بيوتاً ماهرين بنحتها، أَشِرين بَطِرين."},{"id":"3082","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"150","aya_text":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","aya_text_emlaey":"فاتقوا الله وأطيعون","aya_tafseer":"[150] فخافوا عقوبة الله، واقبلوا نصحي،"},{"id":"3083","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"151","aya_text":"وَلَا تُطِيعُوٓاْ أَمۡرَ ٱلۡمُسۡرِفِينَ","aya_text_emlaey":"ولا تطيعوا أمر المسرفين","aya_tafseer":"[151] ولا تنقادوا لأمر المسرفين على أنفسهم المتمادين في معصية الله"},{"id":"3084","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"10","aya_no":"152","aya_text":"ٱلَّذِينَ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ","aya_text_emlaey":"الذين يفسدون في الأرض ولا يصلحون","aya_tafseer":"[152] الذين دأبوا على الإفساد في الأرض إفساداً لا إصلاح فيه."},{"id":"3085","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"10","aya_no":"153","aya_text":"قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ","aya_text_emlaey":"قالوا إنما أنت من المسحرين","aya_tafseer":"[153] قالت ثمود لنبيها صالح: ما أنت إلا من الذين سُحروا سِحْراً كثيراً، حتى غلب السحر على عقلك."},{"id":"3086","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"11","aya_no":"154","aya_text":"مَآ أَنتَ إِلَّا بَشَرٞ مِّثۡلُنَا فَأۡتِ بِـَٔايَةٍ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ","aya_text_emlaey":"ما أنت إلا بشر مثلنا فأت بآية إن كنت من الصادقين","aya_tafseer":"[154] ما أنت إلا فرد مماثل لنا في البشرية من بني آدم، فكيف تتميز علينا بالرسالة؟ فأت بحجة واضحة تدل على ثبوت رسالتك، إن كنت صادقاً في دعواك أن الله أرسلك إلينا."},{"id":"3087","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"12","aya_no":"155","aya_text":"قَالَ هَٰذِهِۦ نَاقَةٞ لَّهَا شِرۡبٞ وَلَكُمۡ شِرۡبُ يَوۡمٖ مَّعۡلُومٖ","aya_text_emlaey":"قال هذه ناقة لها شرب ولكم شرب يوم معلوم","aya_tafseer":"[155] قال لهم صالح -وقد أتاهم بناقة أخرجها الله له من الصخرة-: هذه ناقة الله لها نصيب من الماء في يوم معلوم، ولكم نصيب منه في يوم آخر، ليس لكم أن تشربوا في اليوم الذي هو نصيبها، ولا هي تشرب في اليوم الذي هو نصيبكم،"},{"id":"3088","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"13","aya_no":"156","aya_text":"وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابُ يَوۡمٍ عَظِيمٖ","aya_text_emlaey":"ولا تمسوها بسوء فيأخذكم عذاب يوم عظيم","aya_tafseer":"[156] ولا تنالوها بشيء مما يسوءها كضَرْبٍ أو قتل أو نحو ذلك، فيهلككم الله بعذابِ يومٍ تعظم شدته؛ بسبب ما يقع فيه من الهول والشدة."},{"id":"3089","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"14","aya_no":"157","aya_text":"فَعَقَرُوهَا فَأَصۡبَحُواْ نَٰدِمِينَ","aya_text_emlaey":"فعقروها فأصبحوا نادمين","aya_tafseer":"[157] فنحروا الناقة، فأصبحوا متحسرين على ما فعلوا لَمَّا أيقنوا بالعذاب، فلم ينفعهم ندمهم."},{"id":"3090","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"15","aya_no":"158","aya_text":"فَأَخَذَهُمُ ٱلۡعَذَابُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ","aya_text_emlaey":"فأخذهم العذاب إن في ذلك لآية وما كان أكثرهم مؤمنين","aya_tafseer":"[158] فنزل بهم عذاب الله الذي توعدهم به صالح عليه السلام، فأهلكهم. إن في إهلاك ثمود لَعبرة لمن اعتبر بهذا المصير، وما كان أكثرهم مؤمنين."},{"id":"3091","jozz":"19","page":"373","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"159","aya_text":"وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","aya_text_emlaey":"وإن ربك لهو العزيز الرحيم","aya_tafseer":"[159] وإن ربك لهو العزيز القاهر المنتقم من أعدائه المكذبين، الرحيم بمن آمن من خلقه."},{"id":"3092","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"160","aya_text":"كَذَّبَتۡ قَوۡمُ لُوطٍ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"كذبت قوم لوط المرسلين","aya_tafseer":"[160] كَذَّبت قوم لوط برسالته، فكانوا بهذا مكذبين لسائر رسل الله؛ لأن ما جاؤوا به من التوحيد وأصول الشرائع واحد."},{"id":"3093","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"2","aya_no":"161","aya_text":"إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ لُوطٌ أَلَا تَتَّقُونَ","aya_text_emlaey":"إذ قال لهم أخوهم لوط ألا تتقون","aya_tafseer":"[161] إذ قال لهم أخوهم لوط: ألا تخشون عذاب الله؟"},{"id":"3094","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"2","aya_no":"162","aya_text":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","aya_text_emlaey":"إني لكم رسول أمين","aya_tafseer":"[162] إني رسول من ربكم، أمين على تبليغ رسالته إليكم،"},{"id":"3095","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"2","aya_no":"163","aya_text":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","aya_text_emlaey":"فاتقوا الله وأطيعون","aya_tafseer":"[163] فاحذروا عقاب الله على تكذيبكم رسوله، واتبعوني فيما دعوتكم إليه،"},{"id":"3096","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"3","aya_no":"164","aya_text":"وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"وما أسألكم عليه من أجر إن أجري إلا على رب العالمين","aya_tafseer":"[164] وما أسألكم على دعوتي لهدايتكم أيَّ أجر، ما أجري إلا على رب العالمين."},{"id":"3097","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"4","aya_no":"165","aya_text":"أَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"أتأتون الذكران من العالمين","aya_tafseer":"[165] أتنكحون الذكور مِن بني آدم،"},{"id":"3098","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"5","aya_no":"166","aya_text":"وَتَذَرُونَ مَا خَلَقَ لَكُمۡ رَبُّكُم مِّنۡ أَزۡوَٰجِكُمۚ بَلۡ أَنتُمۡ قَوۡمٌ عَادُونَ","aya_text_emlaey":"وتذرون ما خلق لكم ربكم من أزواجكم بل أنتم قوم عادون","aya_tafseer":"[166] وتتركون ما خلق الله لاستمتاعكم وتناسلكم مِن أزواجكم؟ بل أنتم قوم -بهذه المعصية- متجاوزون ما أباحه الله لكم من الحلال إلى الحرام."},{"id":"3099","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"6","aya_no":"167","aya_text":"قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِينَ","aya_text_emlaey":"قالوا لئن لم تنته يالوط لتكونن من المخرجين","aya_tafseer":"[167] قال قوم لوط: لئن لم تترك يا لوط نَهْيَنا عن إتيان الذكور وتقبيح فعله، لتكونن من المطرودين من بلادنا."},{"id":"3100","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"168","aya_text":"قَالَ إِنِّي لِعَمَلِكُم مِّنَ ٱلۡقَالِينَ","aya_text_emlaey":"قال إني لعملكم من القالين","aya_tafseer":"[168] قال لوط لهم: إني لِعملكم الذي تعملونه من إتيان الذكور، لمن المبغضين له بغضاً شديداً."},{"id":"3101","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"169","aya_text":"رَبِّ نَجِّنِي وَأَهۡلِي مِمَّا يَعۡمَلُونَ","aya_text_emlaey":"رب نجني وأهلي مما يعملون","aya_tafseer":"[169] ثم دعا لوط ربه حينما يئس من استجابتهم له قائلاً: ربِّ أنقذني وأنقذ أهلي مما يعمله قومي مِن هذه المعصية القبيحة، ومِن عقوبتك التي ستصيبهم."},{"id":"3102","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"170","aya_text":"فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ","aya_text_emlaey":"فنجيناه وأهله أجمعين","aya_tafseer":"[170] فنجيناه وأهل بيته والمستجيبين لدعوته أجمعين"},{"id":"3103","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"171","aya_text":"إِلَّا عَجُوزٗا فِي ٱلۡغَٰبِرِينَ","aya_text_emlaey":"إلا عجوزا في الغابرين","aya_tafseer":"[171] إلا عجوزاً من أهله، وهي امرأته لم تشاركهم في الإيمان، فكانت من الباقين في العذاب والهلاك."},{"id":"3104","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"172","aya_text":"ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ","aya_text_emlaey":"ثم دمرنا الآخرين","aya_tafseer":"[172] ثم أهلكنا مَن عداهم من الكفرة أشدَّ إهلاك،"},{"id":"3105","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"9","aya_no":"173","aya_text":"وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ","aya_text_emlaey":"وأمطرنا عليهم مطرا فساء مطر المنذرين","aya_tafseer":"[173] ، وأنزلنا عليهم حجارة من السماء كالمطر أهلكتهم، فقَبُحَ مطرُ مَن أنذرهم رسلهم ولم يستجيبوا لهم؛ فقد أُنزل بهم أشدُّ أنواع الهلاك والتدمير."},{"id":"3106","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"10","aya_no":"174","aya_text":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ","aya_text_emlaey":"إن في ذلك لآية وما كان أكثرهم مؤمنين","aya_tafseer":"[174] إن في ذلك العقاب الذي نزل بقوم لوط لَعبرة وموعظة، يتعظ بها المكذبون. وما كان أكثرهم مؤمنين."},{"id":"3107","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"10","aya_no":"175","aya_text":"وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","aya_text_emlaey":"وإن ربك لهو العزيز الرحيم","aya_tafseer":"[175] وإن ربك لهو العزيز الغالب الذي يقهر المكذبين، الرحيم بعباده المؤمنين."},{"id":"3108","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"11","aya_no":"176","aya_text":"كَذَّبَ أَصۡحَٰبُ لۡـَٔيۡكَةِ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"كذب أصحاب الأيكة المرسلين","aya_tafseer":"[176] كذَّب أصحابُ الأرض ذات الشجر الملتف رسولَهم شعيباً في رسالته، فكانوا بهذا مكذِّبين لجميع الرسالات."},{"id":"3109","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"11","aya_no":"177","aya_text":"إِذۡ قَالَ لَهُمۡ شُعَيۡبٌ أَلَا تَتَّقُونَ","aya_text_emlaey":"إذ قال لهم شعيب ألا تتقون","aya_tafseer":"[177] إذ قال لهم شعيب: ألا تخشون عقاب الله على شرككم ومعاصيكم؟"},{"id":"3110","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"12","aya_no":"178","aya_text":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","aya_text_emlaey":"إني لكم رسول أمين","aya_tafseer":"[178] إني مرسَل إليكم مِنَ الله لهدايتكم، حفيظ على ما أوحى الله به إليَّ من الرسالة،"},{"id":"3111","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"12","aya_no":"179","aya_text":"فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ","aya_text_emlaey":"فاتقوا الله وأطيعون","aya_tafseer":"[179] فخافوا عقاب الله، واتبعوا ما دعوتكم إليه مِن هداية الله؛ لترشُدوا،"},{"id":"3112","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"13","aya_no":"180","aya_text":"وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"وما أسألكم عليه من أجر إن أجري إلا على رب العالمين","aya_tafseer":"[180] وما أطلب منكم على دعائي لكم إلى الإيمان بالله أيَّ جزاء، ما جزائي إلا على رب العالمين."},{"id":"3113","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"14","aya_no":"181","aya_text":"۞ أَوۡفُواْ ٱلۡكَيۡلَ وَلَا تَكُونُواْ مِنَ ٱلۡمُخۡسِرِينَ","aya_text_emlaey":"أوفوا الكيل ولا تكونوا من المخسرين","aya_tafseer":"[181] قال لهم شعيب -وقد كانوا يُنْقِصون الكيل والميزان-: أتمُّوا الكيل للناس وافياً لهم، ولا تكونوا ممن يُنْقِصون الناس حقوقهم،"},{"id":"3114","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"14","aya_no":"182","aya_text":"وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ","aya_text_emlaey":"وزنوا بالقسطاس المستقيم","aya_tafseer":"[182] وَزِنوا بالميزان العدل المستقيم،"},{"id":"3115","jozz":"19","page":"374","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"183","aya_text":"وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","aya_text_emlaey":"ولا تبخسوا الناس أشياءهم ولا تعثوا في الأرض مفسدين","aya_tafseer":"[183] ولا تنقصوا الناس شيئاً مِن حقوقهم في كيل أو وزن أو غير ذلك، ولا تكثروا في الأرض الفساد، بالشرك والقتل والنهب وتخويف الناس وارتكاب المعاصي."},{"id":"3116","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"184","aya_text":"وَٱتَّقُواْ ٱلَّذِي خَلَقَكُمۡ وَٱلۡجِبِلَّةَ ٱلۡأَوَّلِينَ","aya_text_emlaey":"واتقوا الذي خلقكم والجبلة الأولين","aya_tafseer":"[184] واحذروا عقوبة الله الذي خلقكم وخلق الأمم المتقدمة عليكم."},{"id":"3117","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"2","aya_no":"185","aya_text":"قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ","aya_text_emlaey":"قالوا إنما أنت من المسحرين","aya_tafseer":"[185] قالوا: إنما أنت -يا شعيب- مِنَ الذين أصابهم السحر إصابة شديدة، فذهب بعقولهم،"},{"id":"3118","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"3","aya_no":"186","aya_text":"وَمَآ أَنتَ إِلَّا بَشَرٞ مِّثۡلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلۡكَٰذِبِينَ","aya_text_emlaey":"وما أنت إلا بشر مثلنا وإن نظنك لمن الكاذبين","aya_tafseer":"[186] وما أنت إلا واحد مثلنا في البشرية، فكيف تختص دوننا بالرسالة؟ وإن أكبر ظننا أنك من الكاذبين فيما تدَّعيه من الرسالة."},{"id":"3119","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"4","aya_no":"187","aya_text":"فَأَسۡقِطۡ عَلَيۡنَا كِسَفٗا مِّنَ ٱلسَّمَآءِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ","aya_text_emlaey":"فأسقط علينا كسفا من السماء إن كنت من الصادقين","aya_tafseer":"[187] فإن كنت صادقاً في دعوى النبوة، فادع الله أن يسقط علينا قطع عذاب من السماء تستأصلنا."},{"id":"3120","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"4","aya_no":"188","aya_text":"قَالَ رَبِّيٓ أَعۡلَمُ بِمَا تَعۡمَلُونَ","aya_text_emlaey":"قال ربي أعلم بما تعملون","aya_tafseer":"[188] قال لهم شعيب: ربي أعلم بما تعملونه مِنَ الشرك والمعاصي، وبما تستوجبونه من العقاب."},{"id":"3121","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"5","aya_no":"189","aya_text":"فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ يَوۡمِ ٱلظُّلَّةِۚ إِنَّهُۥ كَانَ عَذَابَ يَوۡمٍ عَظِيمٍ","aya_text_emlaey":"فكذبوه فأخذهم عذاب يوم الظلة إنه كان عذاب يوم عظيم","aya_tafseer":"[189] فاستمَرُّوا على تكذيبه، فأصابهم الحر الشديد، وصاروا يبحثون عن ملاذ يستظلون به، فأظلتهم سحابة، وجدوا لها برداً ونسيماً، فلما اجتمعوا تحتها التهبت عليهم ناراً فأحرقتهم، فكان هلاكهم جميعاً في يوم شديد الهول."},{"id":"3122","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"190","aya_text":"إِنَّ فِي ذَٰلِكَ لَأٓيَةٗۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ","aya_text_emlaey":"إن في ذلك لآية وما كان أكثرهم مؤمنين","aya_tafseer":"[190] إن في ذلك العقاب الذي نزل بهم، لَدلالة واضحة على قدرة الله في مؤاخذة المكذبين، وعبرة لمن يعتبر، وما كان أكثرهم مؤمنين متعظين بذلك."},{"id":"3123","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"7","aya_no":"191","aya_text":"وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ","aya_text_emlaey":"وإن ربك لهو العزيز الرحيم","aya_tafseer":"[191] وإن ربك -أيها الرسول- لهو العزيز في نقمته ممن انتقم منه من أعدائه، الرحيم بعباده الموحدين."},{"id":"3124","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"192","aya_text":"وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"وإنه لتنـزيل رب العالمين","aya_tafseer":"[192] وإن هذا القرآن الذي ذُكِرَتْ فيه هذه القصص الصادقة، لَمنزَّل مِن خالق الخلق، ومالك الأمر كله،"},{"id":"3125","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"8","aya_no":"193","aya_text":"نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِينُ","aya_text_emlaey":"نـزل به الروح الأمين","aya_tafseer":"[193] نزل به جبريل الأمين،"},{"id":"3126","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"194","aya_text":"عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِينَ","aya_text_emlaey":"على قلبك لتكون من المنذرين","aya_tafseer":"[194] فتلاه عليك -أيها الرسول- حتى وعيته بقلبك حفظاً وفهماً؛ لتكون مِن رسل الله الذين يخوِّفون قومهم عقاب الله، فتنذر بهذا التنزيل الإنس والجن أجمعين."},{"id":"3127","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"9","aya_no":"195","aya_text":"بِلِسَانٍ عَرَبِيّٖ مُّبِينٖ","aya_text_emlaey":"بلسان عربي مبين","aya_tafseer":"[195] نزل به جبريل عليك بلغة عربية واضحة المعنى، ظاهرة الدلالة، فيما يحتاجون إليه في إصلاح شؤون دينهم ودنياهم."},{"id":"3128","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"196","aya_text":"وَإِنَّهُۥ لَفِي زُبُرِ ٱلۡأَوَّلِينَ","aya_text_emlaey":"وإنه لفي زبر الأولين","aya_tafseer":"[196] وإنَّ ذِكْرَ هذا القرآن لَمثبتٌ في كتب الأنبياء السابقين، قد بَشَّرَتْ به وصَدَّقَتْه."},{"id":"3129","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"10","aya_no":"197","aya_text":"أَوَلَمۡ يَكُن لَّهُمۡ ءَايَةً أَن يَعۡلَمَهُۥ عُلَمَٰٓؤُاْ بَنِيٓ إِسۡرَٰٓءِيلَ","aya_text_emlaey":"أو لم يكن لهم آية أن يعلمه علماء بني إسرائيل","aya_tafseer":"[197] أو لم يَكْفِ هؤلاء -في الدلالة على أنك رسول الله، وأن القرآن حق- عِلْمُ علماء بني إسرائيل صحة ذلك، ومَن آمن منهم كعبدالله بن سلام؟"},{"id":"3130","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"11","aya_no":"198","aya_text":"وَلَوۡ نَزَّلۡنَٰهُ عَلَىٰ بَعۡضِ ٱلۡأَعۡجَمِينَ","aya_text_emlaey":"ولو نـزلناه على بعض الأعجمين","aya_tafseer":"[198] ولو نَزَّلنا القرآن على بعض الذين لا يتكلمون بالعربية"},{"id":"3131","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"11","aya_no":"199","aya_text":"فَقَرَأَهُۥ عَلَيۡهِم مَّا كَانُواْ بِهِۦ مُؤۡمِنِينَ","aya_text_emlaey":"فقرأه عليهم ما كانوا به مؤمنين","aya_tafseer":"[199] فقرأه على كفار قريش قراءة عربية صحيحة، لكفروا به أيضاً، وانتحلوا لجحودهم عذراً"},{"id":"3132","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"12","aya_no":"200","aya_text":"كَذَٰلِكَ سَلَكۡنَٰهُ فِي قُلُوبِ ٱلۡمُجۡرِمِينَ","aya_text_emlaey":"كذلك سلكناه في قلوب المجرمين","aya_tafseer":"[200] كذلك أدخلنا في قلوب المجرمين جحود القرآن، وصار متمكناً فيها؛ وذلك بسبب ظلمهم وإجرامهم،"},{"id":"3133","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"13","aya_no":"201","aya_text":"لَا يُؤۡمِنُونَ بِهِۦ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ ٱلۡأَلِيمَ","aya_text_emlaey":"لا يؤمنون به حتى يروا العذاب الأليم","aya_tafseer":"[201] فلا سبيل إلى أن يتغيروا عمَّا هم عليه من إنكار القرآن، حتى يعاينوا العذاب الشديد الذي وُعِدوا به."},{"id":"3134","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"202","aya_text":"فَيَأۡتِيَهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ","aya_text_emlaey":"فيأتيهم بغتة وهم لا يشعرون","aya_tafseer":"[202] فينزل بهم العذاب فجأة، وهم لا يعلمون قبل ذلك بمجيئه،"},{"id":"3135","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"14","aya_no":"203","aya_text":"فَيَقُولُواْ هَلۡ نَحۡنُ مُنظَرُونَ","aya_text_emlaey":"فيقولوا هل نحن منظرون","aya_tafseer":"[203] فيقولون عند مفاجأتهم به تحسُّراً على ما فاتهم من الإيمان: هل نحن مُمْهَلون مُؤخَّرون؛ لنتوب إلى الله مِن شركنا، ونستدرك ما فاتنا؟"},{"id":"3136","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"14","aya_no":"204","aya_text":"أَفَبِعَذَابِنَا يَسۡتَعۡجِلُونَ","aya_text_emlaey":"أفبعذابنا يستعجلون","aya_tafseer":"[204] أَغَرَّ هؤلاء إمهالي، فيستعجلون نزول العذاب عليهم من السماء؟"},{"id":"3137","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"14","line_end":"15","aya_no":"205","aya_text":"أَفَرَءَيۡتَ إِن مَّتَّعۡنَٰهُمۡ سِنِينَ","aya_text_emlaey":"أفرأيت إن متعناهم سنين","aya_tafseer":"[205] أفعلمت -أيها الرسول- إن مَتَّعناهم بالحياة سنين طويلة بتأخير آجالهم،"},{"id":"3138","jozz":"19","page":"375","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"15","line_end":"15","aya_no":"206","aya_text":"ثُمَّ جَآءَهُم مَّا كَانُواْ يُوعَدُونَ","aya_text_emlaey":"ثم جاءهم ما كانوا يوعدون","aya_tafseer":"[206] ثم نزل بهم العذاب الموعود؟"},{"id":"3139","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"1","aya_no":"207","aya_text":"مَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يُمَتَّعُونَ","aya_text_emlaey":"ما أغنى عنهم ما كانوا يمتعون","aya_tafseer":"[207] ما أغنى عنهم تمتعهم بطول العمر، وطيب العيش، إذا لم يتوبوا من شركهم؟ فعذاب الله واقع بهم عاجلاً أم آجلاً."},{"id":"3140","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"1","line_end":"2","aya_no":"208","aya_text":"وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا لَهَا مُنذِرُونَ","aya_text_emlaey":"وما أهلكنا من قرية إلا لها منذرون","aya_tafseer":"[208] وما أهلكنا مِن قرية من القرى في الأمم جميعاً، إلا بعد أن نرسل إليهم رسلاً ينذرونهم"},{"id":"3141","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"2","line_end":"3","aya_no":"209","aya_text":"ذِكۡرَىٰ وَمَا كُنَّا ظَٰلِمِينَ","aya_text_emlaey":"ذكرى وما كنا ظالمين","aya_tafseer":"[209] تذكرة لهم وتنبيهاً على ما فيه نجاتهم، وما كنا ظالمين فنعذب أمة قبل أن نرسل إليها رسولاً."},{"id":"3142","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"3","aya_no":"210","aya_text":"وَمَا تَنَزَّلَتۡ بِهِ ٱلشَّيَٰطِينُ","aya_text_emlaey":"وما تنـزلت به الشياطين","aya_tafseer":"[210] وما تَنَزَّلَتْ بالقرآن على محمد صلى الله عليه وسلم الشياطين كما يزعم الكفرة"},{"id":"3143","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"3","line_end":"4","aya_no":"211","aya_text":"وَمَا يَنۢبَغِي لَهُمۡ وَمَا يَسۡتَطِيعُونَ","aya_text_emlaey":"وما ينبغي لهم وما يستطيعون","aya_tafseer":"[211] ولا يصح منهم ذلك، وما يستطيعونه؛"},{"id":"3144","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"4","line_end":"4","aya_no":"212","aya_text":"إِنَّهُمۡ عَنِ ٱلسَّمۡعِ لَمَعۡزُولُونَ","aya_text_emlaey":"إنهم عن السمع لمعزولون","aya_tafseer":"[212] لأنهم عن استماع القرآن من السماء محجوبون مرجومون بالشهب."},{"id":"3145","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"5","line_end":"5","aya_no":"213","aya_text":"فَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلۡمُعَذَّبِينَ","aya_text_emlaey":"فلا تدع مع الله إلها آخر فتكون من المعذبين","aya_tafseer":"[213] فلا تعبد مع الله معبوداً غيره، فينزل بك من العذاب ما نزل بهؤلاء الذين عبدوا مع الله غيره."},{"id":"3146","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"6","aya_no":"214","aya_text":"وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ","aya_text_emlaey":"وأنذر عشيرتك الأقربين","aya_tafseer":"[214] وحَذِّر -أيها الرسول- الأقرب فالأقرب مِن قومك، مِن عذابنا، أن ينزل بهم."},{"id":"3147","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"6","line_end":"7","aya_no":"215","aya_text":"وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"واخفض جناحك لمن اتبعك من المؤمنين","aya_tafseer":"[215] وأَلِنْ جانبك وكلامك تواضعاً ورحمة لمن ظهر لك منه إجابة دعوتك."},{"id":"3148","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"7","line_end":"7","aya_no":"216","aya_text":"فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي بَرِيٓءٞ مِّمَّا تَعۡمَلُونَ","aya_text_emlaey":"فإن عصوك فقل إني بريء مما تعملون","aya_tafseer":"[216] فإن خالفوا أمرك ولم يتبعوك، فتبرَّأ من أعمالهم، وما هم عليه من الشرك والضلال."},{"id":"3149","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"217","aya_text":"وَتَوَكَّلۡ عَلَى ٱلۡعَزِيزِ ٱلرَّحِيمِ","aya_text_emlaey":"وتوكل على العزيز الرحيم","aya_tafseer":"[217] وفَوِّضْ أمرك إلى الله العزيز الذي لا يغالَب ولا يُقْهَر، الرحيم الذي لا يخذل أولياءه،"},{"id":"3150","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"8","line_end":"8","aya_no":"218","aya_text":"ٱلَّذِي يَرَىٰكَ حِينَ تَقُومُ","aya_text_emlaey":"الذي يراك حين تقوم","aya_tafseer":"[218] وهو الذي يراك حين تقوم للصلاة وحدك في جوف الليل"},{"id":"3151","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"219","aya_text":"وَتَقَلُّبَكَ فِي ٱلسَّٰجِدِينَ","aya_text_emlaey":"وتقلبك في الساجدين","aya_tafseer":"[219] ويرى تقلُّبك مع الساجدين في صلاتهم معك قائماً وراكعاً وساجداً وجالساً"},{"id":"3152","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"9","line_end":"9","aya_no":"220","aya_text":"إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","aya_text_emlaey":"إنه هو السميع العليم","aya_tafseer":"[220] إنه -سبحانه- هو السميع لتلاوتك وذكرك، العليم بنيتك وعملك."},{"id":"3153","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"10","aya_no":"221","aya_text":"هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ","aya_text_emlaey":"هل أنبئكم على من تنـزل الشياطين","aya_tafseer":"[221] هل أخبركم -أيها الناس- على مَن تنزَّل الشياطين؟"},{"id":"3154","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"10","line_end":"11","aya_no":"222","aya_text":"تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٖ","aya_text_emlaey":"تنـزل على كل أفاك أثيم","aya_tafseer":"[222] تتنزل على كل كذَّاب كثير الآثام من الكهنة،"},{"id":"3155","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"11","line_end":"11","aya_no":"223","aya_text":"يُلۡقُونَ ٱلسَّمۡعَ وَأَكۡثَرُهُمۡ كَٰذِبُونَ","aya_text_emlaey":"يلقون السمع وأكثرهم كاذبون","aya_tafseer":"[223] يَسْتَرِقُ الشياطين السمع، يتخطفونه من الملأ الأعلى، فيلقونه إلى الكهان، ومَن جرى مجراهم مِنَ الفسقة، وأكثر هؤلاء كاذبون، يَصْدُق أحدهم في كلمة، فيزيد فيها أكثر مِن مائة كذبة."},{"id":"3156","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"12","aya_no":"224","aya_text":"وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلۡغَاوُۥنَ","aya_text_emlaey":"والشعراء يتبعهم الغاوون","aya_tafseer":"[224] والشعراء يقوم شعرهم على الباطل والكذب، ويجاريهم الضالون الزائغون مِن أمثالهم"},{"id":"3157","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"12","line_end":"13","aya_no":"225","aya_text":"أَلَمۡ تَرَ أَنَّهُمۡ فِي كُلِّ وَادٖ يَهِيمُونَ","aya_text_emlaey":"ألم تر أنهم في كل واد يهيمون","aya_tafseer":"[225] ألم تر -أيها النبي- أنهم يذهبون كالهائم على وجهه، يخوضون في كل فن مِن فنون الكذب والزور وتمزيق الأعراض والطعن في الأنساب وتجريح النساء العفائف"},{"id":"3158","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"13","aya_no":"226","aya_text":"وَأَنَّهُمۡ يَقُولُونَ مَا لَا يَفۡعَلُونَ","aya_text_emlaey":"وأنهم يقولون ما لا يفعلون","aya_tafseer":"[226] وأنهم يقولون ما لا يفعلون، يبالغون في مدح أهل الباطل، وينتقصون أهل الحق؟"},{"id":"3159","jozz":"19","page":"376","sura_no":"26","sura_name_en":"Ash-Shu‘arā’","sura_name_ar":"الشعراء ","line_start":"13","line_end":"15","aya_no":"227","aya_text":"إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَذَكَرُواْ ٱللَّهَ كَثِيرٗا وَٱنتَصَرُواْ مِنۢ بَعۡدِ مَا ظُلِمُواْۗ وَسَيَعۡلَمُ ٱلَّذِينَ ظَلَمُوٓاْ أَيَّ مُنقَلَبٖ يَنقَلِبُونَ","aya_text_emlaey":"إلا الذين آمنوا وعملوا الصالحات وذكروا الله كثيرا وانتصروا من بعد ما ظلموا وسيعلم الذين ظلموا أي منقلب ينقلبون","aya_tafseer":"[227] استثنى الله من الشعراءِ الشعراءَ الذين اهتدَوْا بالإيمان وعملوا الصالحات، وأكثروا مِن ذِكْر الله فقالوا الشعر في توحيد الله -سبحانه- والثناء عليه جلَّ ذكره، والدفاع عن رسوله محمد -صلى الله عليه وسلم-، وتكلموا بالحكمة والموعظة والآداب الحسنة، وانتصروا للإسلام، يهجون مَن يهجوه أو يهجو رسوله؛ ردّاً على الشعراء الكافرين. وسيعلم الذين ظلموا أنفسهم بالشرك والمعاصي، وظلموا غيرهم بغمط حقوقهم، أو الاعتداء عليهم، أو بالتُّهم الباطلة، أي مرجع من مراجع الشر والهلاك يرجعون إليه؟ إنَّه منقلب سوء، نسأل الله السلامة والعافية."}]
